function useToggle(initial: boolean): [boolean, () => void] {
  let state = initial;
  const toggle = () => { state = !state; };
  return [state, toggle];
}

const [isOpen, toggle] = useToggle(false);
console.log(isOpen); // false
toggle();
console.log(typeof toggle); // 'function'

